import { contextBridge, ipcRenderer } from 'electron';

// Expose protected methods that allow the renderer process to use
// specific Electron APIs without exposing the entire Electron API
contextBridge.exposeInMainWorld('electron', {
  platform: process.platform,
  getHardwareId: () => ipcRenderer.invoke('getHardwareId'),
  getSystemMemory: () => ipcRenderer.sendSync('get-system-memory'),
  licenseActivate: (email: string, licenseKey: string) => ipcRenderer.invoke('license:activate', email, licenseKey),
  licenseGetStatus: () => ipcRenderer.invoke('license:getStatus'),
  licensePeriodicCheck: () => ipcRenderer.invoke('license:periodicCheck'),
  licenseClear: () => ipcRenderer.invoke('license:clear'),
  logToFile: (level: string, ...args: unknown[]) => ipcRenderer.send('log:write', level, ...args),
  openExternal: (url: string) => {
    // Use shell.openExternal from main process for security
    ipcRenderer.send('open-external', url);
  },
  // Licensing API - bypasses CORS by running in main process
  licensingFetch: (url: string, options: { method?: string; headers?: Record<string, string>; body?: string | ArrayBuffer }) =>
    ipcRenderer.invoke('licensing:fetch', url, options),
  // Keep backward compatibility
  showSaveDialog: (options: {
    defaultPath?: string;
    filters?: { name: string; extensions: string[] }[];
  }) => ipcRenderer.invoke('show-save-dialog', options),
  writeFile: (filePath: string, dataUrl: string) => 
    ipcRenderer.invoke('write-file', filePath, dataUrl),
  writeFileBinary: (filePath: string, arrayBuffer: ArrayBuffer) =>
    ipcRenderer.invoke('write-file-binary', filePath, arrayBuffer),
  readFile: (filePath: string) => ipcRenderer.invoke('read-file', filePath),
  readDirectory: (dirPath: string) => ipcRenderer.invoke('read-directory', dirPath),
  createDirectory: (dirPath: string) => ipcRenderer.invoke('create-directory', dirPath),
  ditherProcess: (payload: {
    algorithmId: string;
    width: number;
    height: number;
    buffer: ArrayBuffer;
    params: { palette: string[]; orderedCycling?: boolean; scale: number; luminanceThreshold?: number; controls: Record<string, unknown> };
  }) => ipcRenderer.invoke('dither:process', payload),
  halftoneProcess: (payload: {
    width: number;
    height: number;
    buffer: ArrayBuffer;
    params: any;
  }) => ipcRenderer.invoke('halftone:process', payload),
  logToMain: (message: string) => ipcRenderer.send('log:renderer', message),
  loadLegacyPalettes: () => ipcRenderer.invoke('load-legacy-palettes'),
  savePaletteToLegacy: (data: unknown) => ipcRenderer.invoke('save-palette-to-legacy', data),
  bulkImportPalettesFromFolder: (folderPath: string, recursive: boolean) =>
    ipcRenderer.invoke('bulk-import-palettes-from-folder', folderPath, recursive),
  bulkImportPalettesFromZip: (zipPath: string, recursive: boolean) =>
    ipcRenderer.invoke('bulk-import-palettes-from-zip', zipPath, recursive),
  // New dialog API
  dialog: {
    showOpenDialog: (options: any) => ipcRenderer.invoke('dialog:openDialog', options),
    showSaveDialog: (options: {
      defaultPath?: string;
      filters?: { name: string; extensions: string[] }[];
    }) => ipcRenderer.invoke('show-save-dialog', options),
  },
  // Clipboard API - uses IPC to access clipboard from main process
  clipboard: {
    readImage: () => ipcRenderer.invoke('clipboard:readImage'),
    writeImage: (dataUrl: string) => ipcRenderer.invoke('clipboard:writeImage', dataUrl),
  },
  // Close confirmation
  onCloseRequested: (callback: () => void) => {
    const listener = (_event: any) => callback();
    ipcRenderer.on('close-requested', listener);
    return () => ipcRenderer.removeListener('close-requested', listener);
  },
  allowClose: () => ipcRenderer.send('allow-close'),
  cancelClose: () => ipcRenderer.send('cancel-close'),
  // Window controls (fullscreen, center) - macOS and Windows
  toggleFullscreen: () => ipcRenderer.invoke('window:toggleFullscreen'),
  centerWindow: () => ipcRenderer.invoke('window:center'),
  // Fullscreen state change listeners
  onFullscreenWillChange: (callback: (willBeFullscreen: boolean) => void) => {
    const listener = (_event: any, willBeFullscreen: boolean) => callback(willBeFullscreen);
    ipcRenderer.on('fullscreen-will-change', listener);
    return () => ipcRenderer.removeListener('fullscreen-will-change', listener);
  },
  onFullscreenChanged: (callback: (isFullscreen: boolean) => void) => {
    const listener = (_event: any, isFullscreen: boolean) => callback(isFullscreen);
    ipcRenderer.on('fullscreen-changed', listener);
    return () => ipcRenderer.removeListener('fullscreen-changed', listener);
  },
  // Discord Rich Presence
  discord: {
    start: (data: any) => ipcRenderer.send('discord:start', data),
    update: (data: any) => ipcRenderer.send('discord:update', data),
    updateStyle: (style: string) => ipcRenderer.send('discord:updateStyle', style),
    clear: () => ipcRenderer.send('discord:clear'),
  },
  // Logs
  getLogCount: () => ipcRenderer.invoke('get-log-count'),
  openLogsFolder: () => ipcRenderer.invoke('open-logs-folder'),
  // Licenses
  readLicensesFile: () => ipcRenderer.invoke('read-licenses-file'),
  // Native FFmpeg management
  ffmpeg: {
    getStatus: () => ipcRenderer.invoke('ffmpeg:getStatus'),
    download: () => ipcRenderer.invoke('ffmpeg:download'),
    uninstall: () => ipcRenderer.invoke('ffmpeg:uninstall'),
    getTempDir: () => ipcRenderer.invoke('ffmpeg:getTempDir'),
    cleanupTempDir: (dir: string) => ipcRenderer.invoke('ffmpeg:cleanupTempDir', dir),
    execNative: (args: string[]) => ipcRenderer.invoke('ffmpeg:execNative', args),
    readFramesDir: (dir: string) => ipcRenderer.invoke('ffmpeg:readFramesDir', dir),
    onDownloadProgress: (callback: (data: any) => void) => {
      const listener = (_event: any, data: any) => callback(data);
      ipcRenderer.on('ffmpeg:download-progress', listener);
      return () => ipcRenderer.removeListener('ffmpeg:download-progress', listener);
    },
    onExecProgress: (callback: (data: any) => void) => {
      const listener = (_event: any, data: any) => callback(data);
      ipcRenderer.on('ffmpeg:exec-progress', listener);
      return () => ipcRenderer.removeListener('ffmpeg:exec-progress', listener);
    },
  },
});

